internal fun teachTypography(fonts: TeachFonts): TeachTypography {
    fun style(
        family: androidx.compose.ui.text.font.FontFamily,
        weight: Int,
        size: Float,
        line: Float,
        spacing: Float,
        features: String? = null,
    ) = TextStyle(
        fontFamily = family,
        fontWeight = FontWeight(weight),
        fontSize = size.sp,
        lineHeight = line.sp,
        letterSpacing = spacing.sp,
        fontFeatureSettings = features,
    )
    return TeachTypography(
        ui =
            TeachUiTypography(
                display = style(fonts.ui, 600, 32f, 40f, 0f),
                title1 = style(fonts.ui, 700, 26f, 34f, -0.1f),
                title2 = style(fonts.ui, 600, 21f, 28f, 0f),
                title3 = style(fonts.ui, 600, 18f, 26f, 0f),
                bodyL = style(fonts.ui, 400, 16f, 24f, 0.1f),
                body = style(fonts.ui, 400, 14f, 20f, 0.2f),
                bodyS = style(fonts.ui, 400, 12f, 16f, 0.3f),
                labelL = style(fonts.ui, 700, 16f, 24f, 0.1f),
                label = style(fonts.ui, 600, 14f, 20f, 0.1f),
                labelS = style(fonts.ui, 600, 12f, 16f, 0.3f),
            ),
        reading =
            TeachReadingTypography(
                body = style(fonts.reading, 400, 17f, 28f, 0f),
                bodyStrong = style(fonts.reading, 600, 17f, 28f, 0f),
                question = style(fonts.reading, 500, 18f, 28f, 0f),
                cardFront = style(fonts.reading, 500, 24f, 34f, 0f),
            ),
        code =
            TeachCodeTypography(
                block = style(fonts.code, 400, 14f, 22f, 0f, features = "liga 0, calt 0"),
                inline = style(fonts.code, 400, 15f, 28f, 0f, features = "liga 0, calt 0"),
            ),
    )
}

